&lt;b&gt;Type&lt;/b&gt; poison, blessure ; &lt;b&gt;Jet de sauvegarde&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;DD&lt;/a&gt; 13&lt;br /&gt;
&lt;b&gt;Fr&#233;quence&lt;/b&gt; 1/&lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;round&lt;/a&gt; pendant 6 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Round.html&quot; title=&quot;round&quot;&gt;rounds&lt;/a&gt;&lt;br /&gt;
&lt;b&gt;Effet&lt;/b&gt; 1d4 points d’&lt;a class=&quot;pagelink&quot; href=&quot;Affaiblissement-Temporaire-(Capacit&#233;).html&quot; title=&quot;affaiblissement temporaire&quot;&gt;affaiblissement temporaire&lt;/a&gt; de &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;For&lt;/a&gt; ; &lt;b&gt;Gu&#233;rison&lt;/b&gt; 1 r&#233;ussite
&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;
